#include <stdio.h>
/* 1) 定义表（单一数据源） */
#define COLOR_LIST(X) \
    X(RED,   "#ff0000") \
    X(GREEN, "#00ff00") \
    X(BLUE,  "#0000ff")
/* 2) 用 X-Macro 生成枚举 */
#define X_ENUM(name, hex) COLOR_##name,
typedef enum { COLOR_LIST(X_ENUM) COLOR_COUNT } Color;
/* 3) 用 X-Macro 生成字符串表 */
#define X_STR(name, hex) hex,
static const char* color_hex[] = { COLOR_LIST(X_STR) };
int main(void) {
    printf("颜色数量 = %d\n", COLOR_COUNT);
    printf("GREEN 的十六进制 = %s\n", color_hex[COLOR_GREEN]);
    return 0;
}
